update pages set contenu = '{"sections":[]}'::jsonb where path = '/offres/chantier/demenagement-machines/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Déménagement de machines industrielles","mecanisme":"**À l''arrivée, votre machine ne fait pas que voyager : elle produit.** Remise en service comprise.","cta":"Faire chiffrer mon déménagement de machines","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30"},{"type":"chiffres","chiffres":[{"valeur":"10 %","libelle":"des candidats retenus · entretien technique et entretien comportemental, résultats partagés avec vous."},{"valeur":"+ 100","libelle":"collaborateurs · techniciens salariés, mobilisables partout en France."},{"valeur":"+ 80","libelle":"clients réguliers · sur plus de 120 clients industriels."},{"valeur":"4","libelle":"agences · Lyon (siège), Montréal, Dubaï, Madrid."}]},{"type":"probleme","punchline":"Une machine mal déposée, ce sont deux jours d''immobilisation en plus. Parfois davantage.","puces":[{"accroche":"Le déménageur d''entreprise","texte":"transporte des caisses et des bureaux. Il ne déconnecte pas un automatisme et ne remonte pas une broche au bon couple."},{"accroche":"Le transporteur","texte":"livre au pied du camion. Personne ne rebranche, personne ne répond de la remise en route."},{"accroche":"Vous, au milieu","texte":", seul face aux questions techniques, aux contraintes d''accès et à un planning qui se tend."}]},{"type":"offre","lignes":[{"prestation":{"texte":"**Étude préalable machine par machine**"},"benefice":"Masses, points de levage, réseaux à déconnecter, accès des véhicules. L''imprévu se paie toujours : il est levé avant le devis."},{"prestation":{"texte":"**Consignation et repérage**"},"benefice":"Programmes d''automatisme sauvegardés, câblages et tuyauteries repérés. Le remontage suit un dossier, pas une mémoire."},{"prestation":{"texte":"**Démontage, emballage, conditionnement**"},"benefice":"Caisses, calages, protection anticorrosion. Votre matériel arrive dans l''état où il est parti."},{"prestation":{"texte":"**Manutention lourde et transport**"},"benefice":"Levage dimensionné, grand gabarit compris, autorisations et créneaux d''accès gérés par nous."},{"prestation":{"texte":"**Remontage, raccordements, remise en service**"},"benefice":"Calage, mise à niveau, essais à vide puis en production. La mission se termine à la remise en route, pas à la livraison."},{"prestation":{"texte":"**Stockage temporaire, démantèlement, adaptation des réseaux**"},"benefice":"Sur devis, quand le site d''arrivée n''est pas prêt ou quand une partie du parc ne repart pas."}]},{"type":"deroule","etapes":[{"titre":"L''étude préalable.","texte":"Visite des deux sites, relevé machine par machine, plan d''implantation et planning détaillé. C''est cette étape qui rend le devis fiable."},{"titre":"La préparation.","texte":"Consignation des énergies, sauvegarde des programmes, repérage des câblages, vidange des fluides, protection des éléments fragiles."},{"titre":"Le démontage et l''emballage.","texte":"Dépose dans les règles, conditionnement adapté à chaque équipement, protection dimensionnée pour la distance et pour la durée de stockage."},{"titre":"La manutention et le transport.","texte":"Levage, chargement, transport avec des partenaires spécialisés, coordination des accès et des autorisations."},{"titre":"Le remontage et les raccordements.","texte":"Mise en place sur le plan validé, calage, mise à niveau, raccordement aux énergies et aux réseaux, vérifications de sécurité."},{"titre":"La remise en service.","texte":"Essais à vide, essais en production, réglages de précision, contrôle de la qualité produite, accompagnement de vos opérateurs."}]}]'::jsonb) where path = '/offres/chantier/demenagement-machines/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"garanties","puces":[{"accroche":"Un seul responsable, du premier appel à la remise en route.","texte":"Même interlocuteur pour le transport et pour les essais. Personne ne se renvoie la balle le jour où ça coince."},{"accroche":"Des modes opératoires écrits avant chaque phase de manutention.","texte":"Analyse de risque, respect des règles du site, sécurité de vos équipes comme des nôtres."},{"accroche":"La préparation se fait pendant que vous produisez encore.","texte":"Colisage, travaux du site d''arrivée, préfabrication : l''arrêt réel est réduit au strict déplacement."},{"accroche":"Des habilitations à jour et vérifiables avant la première dépose.","texte":"Démarche MASE pour la sécurité des interventions, évaluation EcoVadis pour la performance RSE : les attestations sont transmises avec chaque plan de prévention, avec les habilitations des techniciens qui entrent sur votre site."}]},{"type":"cta","question":"Besoin de déplacer une machine ou un parc sans casser la cadence ?","bouton":"Faire chiffrer mon déménagement de machines","href":"/contact/","rappel":"04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30, astreinte 24/24 et 7/7."},{"type":"preuves","preuves":[{"titre":"Déplacement et reconfiguration d''équipements, étanchéité et isolation, 2025.","texte":"Transferts de machines sécurisés, sans casse ni improvisation, délais tenus sans pénalité","lienLibelle":"Étude de cas SOPREMA","lienHref":"/preuves/soprema/"},{"titre":"Montage d''un centre logistique, Clermont-Ferrand, 2023.","texte":"12 monteurs mécaniciens, 8 engins de levage, site livré à la date prévue","lienLibelle":"Étude de cas AKTID","lienHref":"/preuves/aktid-centre-logistique/"},{"titre":"Installation et mise en production d''un parc machine, site automobile.","texte":"6 techniciens mobilisés, continuité opérationnelle assurée ensuite","lienLibelle":"Étude de cas EATON","lienHref":"/preuves/eaton-mise-en-production/"},{"titre":"Montage de portiques de lavage sur sites répartis en France.","texte":"Réception, assemblage, levage, raccordements, validation à l''issue du montage","lienLibelle":"Étude de cas ORTHUS x WASHTEC","lienHref":"/preuves/orthus-washtec/"}]}]'::jsonb) where path = '/offres/chantier/demenagement-machines/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"objections","questions":[{"question":"Combien coûte un déménagement de machines industrielles ?","reponse":"Le montant dépend du nombre de machines, de leur masse, des conditions d''accès et de la distance. Il est chiffré sur devis après l''étude préalable, qui est gratuite. En manutention lourde, un prix donné sans visite se corrige toujours à la hausse."},{"question":"Quels types de machines déménagez-vous ?","reponse":"Machine-outil, presse, centre d''usinage, ligne de conditionnement, convoyeur, robot, équipement de laboratoire. Nos domaines couvrent mécanique, électricité, automatisme, hydraulique et pneumatique. Pas de particuliers, pas de bureaux."},{"question":"Assurez-vous aussi le transport et les autorisations ?","reponse":"Oui. Levage, chargement, transport avec des partenaires spécialisés, autorisations et créneaux d''accès : le même responsable répond du transport et de la remise en service."},{"question":"Pouvez-vous stocker nos machines entre deux sites ?","reponse":"Oui, quand le site d''arrivée n''est pas prêt. L''emballage et la protection sont adaptés à la durée, et les modalités figurent au devis."},{"question":"Qui sont les techniciens qui manipulent notre matériel ?","reponse":"Des salariés Migen, évalués en entretien technique et en entretien comportemental. Seuls 10 % des candidats sont retenus, et les résultats d''évaluation vous sont communiqués."},{"question":"Et si une machine ne mérite pas le voyage ?","reponse":"Nous le disons. L''étude tranche entre transfert, remise en état et démantèlement. Migen ne vend pas de machines : le conseil n''est orienté par aucun catalogue."}]},{"type":"ctaFinal","question":"Besoin de savoir si votre machine supporte le déplacement ?","bouton":"Demander une visite d''étude","href":"/contact/","rappel":"04 78 33 72 05, astreinte 24/24 et 7/7."}]'::jsonb) where path = '/offres/chantier/demenagement-machines/';
